import numpy as np
def equation(t, P, params):
    r,K,A,w,ph,b = params[0],params[1],params[2],params[3],params[4],params[5]
    return r*P*(1-P/K) + A*np.sin(w*t+ph) + b*P*np.sin(w*t+ph)

from numpy.linalg import lstsq
def fit(F):
    c=lstsq(F,dP_dt,rcond=None)[0]
    r=dP_dt-F@c
    return np.mean(r**2)/np.var(dP_dt), c
